import { ReactNode, FC } from 'react';

type ToastType = 'info' | 'success' | 'error' | 'warning' | 'loading';
type ToastPosition = 'top' | 'center' | 'bottom';
interface ToastProps {
    /** 是否打开 */
    open: boolean;
    /** 类型 */
    type?: ToastType;
    /** 提示内容 */
    content: string;
    /** 显示位置 */
    position?: ToastPosition;
    /** 显示时长 (ms)，0 表示不自动关闭 */
    duration?: number;
    /** 自定义图标 */
    icon?: ReactNode;
    /** 是否显示遮罩 */
    mask?: boolean;
    /** 关闭回调 */
    onClose?: () => void;
}
interface ToastShowOptions {
    content: string;
    type?: ToastType;
    position?: ToastPosition;
    duration?: number;
    icon?: ReactNode;
    mask?: boolean;
    onClose?: () => void;
}

interface ToastComponent extends FC<ToastProps> {
    show: (options: ToastShowOptions | string) => void;
    success: (content: string, duration?: number) => void;
    error: (content: string, duration?: number) => void;
    loading: (content?: string) => void;
    hide: () => void;
}
declare const Toast: ToastComponent;

export { Toast, Toast as default };
export type { ToastComponent, ToastPosition, ToastProps, ToastShowOptions, ToastType };
